test('Var requires evidence and Uygulanmaz requires reason; read-only cannot edit',()=>{const {dom,w,a,p}=app();a.AKSIYON.islemDuzenle({dataset:{i:'1'}});assert.equal(w.document.querySelector('#modal'),null);a.S.owner=true;a.S.rol={duzenle:true};a.AKSIYON.islemDuzenle({dataset:{i:'1'}});w.document.querySelector('#ikDurum').value='var';w.document.querySelector('#ikKaydet').click();assert.match(w.document.querySelector('#ikHata').textContent,/kaynak/);assert.equal(p.islem_kontrol,undefined);w.document.querySelector('#ikDurum').value='uygulanmaz';w.document.querySelector('#ikKaydet').click();assert.match(w.document.querySelector('#ikHata').textContent,/gerekçe/);assert.equal(p.islem_kontrol,undefined);dom.window.close();});
