test('adding a park refreshes the shared park selector and preserves selection',()=>{const {dom,w,a}=app();w.document.body.insertAdjacentHTML('beforeend','<select id="sSel"></select>');a.S.veri.parks.push({kisa:'Yeni park'});a.S.park='Yeni park';a.parkSecenekleriniYenile();assert.equal(w.document.querySelectorAll('#sSel option').length,2);assert.equal(w.document.querySelector('#sSel').value,'Yeni park');dom.window.close();});
test('new park validation and creation save once and appear in shared lists without invented map geometry',async()=>{const {dom,w,a}=app();try{w.HTMLElement.prototype.scrollIntoView=()=>{};w.document.body.innerHTML='<div id="gate"></div><div id="app"></div>';a.S.veri={parks:[],muhasebe:[],meta:{},kurum:{}};a.S.oran={tufe:{degerler:{}},gz:{oranlar:[['2025-01-01',.037]]},gz_kdv:.2};a.S.owner=true;a.S.rol={duzenle:true};a.S.page='parklar';a.hesapla();a.kabukKur();w.K.sifrele=async v=>JSON.stringify(v);w.K.b64=x=>Buffer.from(x).toString('base64');w.TextEncoder=TextEncoder;let writes=0;w.fetch=async(u,o)=>({ok:true,json:async()=>{if(o.method==='PUT'){writes++;return{content:{sha:'saved'}};}return{sha:'before'};}});a.AKSIYON.parkDuzenle({dataset:{k:''}});await w.document.querySelector('#pkOk').onclick();assert.match(w.document.querySelector('#pkErr').textContent,/Kısa ad/);w.document.querySelector('#pk_kisa').value='Yeni park';w.document.querySelector('#pk_ad').value='Yeni Orman Parkı';w.document.querySelector('#pk_seflik').value='İstanbul';await w.document.querySelector('#pkOk').onclick();assert.equal(writes,1);assert.equal(a.S.dirty,0);assert.equal(a.S.veri.parks.length,1);assert.equal(a.S.pBy['Yeni park'].ad,'Yeni Orman Parkı');assert.equal(a.S.veri.parks[0].harita,undefined);assert.equal(w.document.querySelector('#sSel').value,'Yeni park');assert.match(a.SAYFA.parklar(),/data-k="Yeni park"/);}finally{dom.window.close();}});
test('save conflict preserves draft and does not issue a write or blocking native confirm',async()=>{const {dom,w,a}=app();try{w.document.body.insertAdjacentHTML('beforeend','<div id="sFoot"></div><button id="bKaydet"></button>');a.S.oran={tufe:{},gz:{}};a.S.owner=true;a.S.sha='old';a.S.dirty=1;a.S.oz=[];a.S.gzO=[['2025-01-01',.037]];a.S.rapor='2026-10-15';const methods=[];w.fetch=async(u,o)=>{methods.push(o.method||'GET');return{ok:true,json:async()=>({sha:'new'})};};w.confirm=()=>{throw Error('native confirm must not be used');};await a.kaydet();assert.equal(a.S.dirty,1);assert.equal(a.S.saving,false);assert.equal(methods.includes('PUT'),false);assert.match(w.document.querySelector('[role=dialog]').textContent,/Taslağı indir/);}finally{dom.window.close();}});
test('KML import/export preserves precision and hole geometry and excludes invalid export',()=>{const {dom,w,a,p,g}=app();const xml='<kml><Document><Placemark><name>M1</name><Polygon><outerBoundaryIs><LinearRing><coordinates>28.123456789,41 28.13,41 28.13,41.01 28.123456789,41.01 28.123456789,41</coordinates></LinearRing></outerBoundaryIs><innerBoundaryIs><LinearRing><coordinates>28.125,41.002 28.126,41.002 28.126,41.003 28.125,41.003 28.125,41.002</coordinates></LinearRing></innerBoundaryIs></Polygon></Placemark></Document></kml>';const f=a.kmlOzellik(xml,p)[0];assert.equal(f.c[0][1],28.123456789);assert.equal(f.holes.length,1);f.p='plan';g.f=[f,{g:'A',c:[[41,28],[41.01,28.01],[41.01,28],[41,28.01]],d:'M',p:'plan',ad:'Invalid'}];a.gypHazirla(g,p.kisa);const result=a.kmlUret([p]);assert.match(result,/innerBoundaryIs/);assert.doesNotMatch(result,/<name>Invalid<\/name>/);assert.match(result,/28.123456789/);assert.equal(a.kmlOzellik(result,p).length,1);dom.window.close();});
