test('boundary import retains all independent polygon parts',()=>{const {dom,a}=app();const pg=(x)=>'<Polygon><outerBoundaryIs><LinearRing><coordinates>'+x+',41 '+(x+.01)+',41 '+(x+.01)+',41.01 '+x+',41.01 '+x+',41</coordinates></LinearRing></outerBoundaryIs></Polygon>';const s='<kml><Placemark>'+pg(28)+pg(29)+'</Placemark></kml>';assert.equal(a.kmlSinir(s).length,2);assert.throws(()=>a.kmlSinir('<kml><Placemark><LineString><coordinates>28,41 29,42</coordinates></LineString></Placemark></kml>'),/poligon/);dom.window.close();});
test('skip link focuses content without changing map route or recreating the map',()=>{const {dom,w}=app();w.document.body.insertAdjacentHTML('afterbegin','<a class="skip-link" href="#page">İçeriğe geç</a><div id="app"></div>');const page=w.document.querySelector('#page');page.tabIndex=-1;page.scrollIntoView=()=>{};w.document.querySelector('.skip-link').click();assert.equal(w.location.hash,'#/harita');assert.equal(w.document.activeElement,page);dom.window.close();});
test('dated source review replaces stale missing list while preserving imported plan notes and features',()=>{const {dom,a,p,g}=app();g.eksik=[{konu:'Eski sınır bulunamadı',gerekli:'Eski ihtiyaç'}];g.planlar[0].not='Eski incelemede plan yok';const original=JSON.stringify(g);p.harita={belge_incelemesi:{tarih:'2026-10-14',plan_notu:'İmzalı plan bulundu; KMZ ile eşleştirme gerekli',eksik:[{konu:'Yeni kapsam teyidi',gerekli:'54,71 ha güncel plan'}]}};assert.equal(a.belgeEksikleri(p,g)[0].konu,'Yeni kapsam teyidi');const plan=a.hPlanPanel(p,g),issues=a.hDogrulamaPanel(p,g);assert.match(plan,/İçe aktarma sırasında kaydedilen not/);assert.match(plan,/Eski incelemede plan yok/);assert.match(plan,/KMZ ile eşleştirme gerekli/);assert.match(issues,/Yeni kapsam teyidi/);assert.doesNotMatch(issues,/Eski sınır bulunamadı/);assert.equal(JSON.stringify(g),original);delete p.harita.belge_incelemesi;assert.equal(a.belgeEksikleri(p,g)[0].konu,'Eski sınır bulunamadı');dom.window.close();});
test('update action blocks dirty records, shows progress, and handles another tab activating first',async()=>{const {dom,w,a}=app();const messages=[],listeners={},reg={update:async()=>{},waiting:{postMessage:x=>messages.push(x)},addEventListener:()=>{}};Object.defineProperty(w.navigator,'serviceWorker',{value:{controller:{},register:async()=>reg,addEventListener:(t,f)=>{listeners[t]=f;}}});a.swKur();await Promise.resolve();const b=w.document.querySelector('#band-guncel button');a.S.dirty=1;b.click();assert.equal(messages.length,0);assert.match(w.document.querySelector('#toast').textContent,/kaydedin/);a.S.dirty=0;b.click();assert.deepEqual(JSON.parse(JSON.stringify(messages)),[{type:'ACTIVATE_UPDATE'}]);assert.equal(b.disabled,true);assert.equal(b.textContent,'Güncelleniyor…');a.S.dirty=1;listeners.controllerchange();assert.equal(w.document.querySelector('#band-guncel button').textContent,'Yenile');reg.waiting={postMessage:()=>{}};a.swKur();await Promise.resolve();reg.waiting=null;a.S.dirty=0;w.document.querySelector('#band-guncel button').click();assert.equal(w.document.querySelector('#band-guncel button').textContent,'Yenile');dom.window.close();});

test('inventory park link selects the clicked park and opens its detail route',async()=>{const {dom,w,a}=app();try{w.scrollTo=()=>{};w.HTMLElement.prototype.scrollIntoView=()=>{};w.document.body.innerHTML='<div id="gate"></div><div id="app"></div>';a.S.veri={parks:[{kisa:'Birinci',ad:'Birinci park'},{kisa:'İkinci',ad:'İkinci park'}],muhasebe:[],meta:{},kurum:{}};a.S.oran={tufe:{degerler:{}},gz:{oranlar:[['2025-01-01',.037]]},gz_kdv:.2};a.hesapla();a.S.page='parklar';w.location.hash='#/parklar';a.kabukKur();a.SAYFA.park=()=>'<h1>'+a.S.park+'</h1>';a.sayfaCiz();w.addEventListener('hashchange',a.yonlendir);await new Promise((resolve,reject)=>{const timeout=w.setTimeout(()=>reject(Error('park navigation did not complete')),1000);w.addEventListener('hashchange',()=>{if(w.location.hash==='#/park?p='+encodeURIComponent('İkinci')){w.clearTimeout(timeout);resolve();}});w.document.querySelectorAll('#page tbody .pk')[1].click();});assert.equal(a.S.park,'İkinci');assert.equal(w.location.hash,'#/park?p='+encodeURIComponent('İkinci'));assert.equal(w.document.querySelector('#page h1').textContent,'İkinci');}finally{dom.window.close();}});

function preparedApp(){const x=app(),{w,a}=x;w.scrollTo=()=>{};w.TextEncoder=TextEncoder;w.Uint8Array=Uint8Array;Object.defineProperty(w,'crypto',{value:require('node:crypto').webcrypto});w.HTMLElement.prototype.scrollIntoView=()=>{};w.document.body.innerHTML='<div id="gate"></div><div id="app"></div>';a.S.veri={parks:[{kisa:'Test',soz_bas:'2020-01-01',soz_bit:'2045-12-31',taban:'2020-01-01',ihale_b:100000,durum:'Kirada'}],muhasebe:[],meta:{},kurum:{}};a.S.oran={tufe:{degerler:{}},gz:{oranlar:[['2025-01-01',.037]]},gz_kdv:.2};a.S.enc=JSON.stringify(a.S.veri);a.S.page='parklar';a.hesapla();a.kabukKur();w.K.coz=async text=>JSON.parse(text);return x;}
test('year selectors extend to contract end, grow with new parks and keep unexplained future rent empty',()=>{const {dom,w,a}=preparedApp();try{assert.equal(a.planYillari().at(-1),2045);assert.equal(a.planYillari()[0],2020);const plan=a.planAl(2045).Test;assert.equal(plan.kod,'yilbasi');assert.equal(plan.kira,undefined);a.S.page='tahakkuk';w.document.querySelector('#page').innerHTML=a.SAYFA.tahakkuk();a.AFTER.tahakkuk();const year=w.document.querySelector('#tYear');assert.equal(year.lastElementChild.value,'2045');year.value='2045';year.dispatchEvent(new w.Event('change'));assert.equal(a.S.tY,2045);assert.match(w.document.querySelector('#page').textContent,/Yılbaşı bekleniyor/);a.S.veri.parks.push({kisa:'Uzayan',soz_bas:'2026-01-01',soz_bit:'2050-12-31'});a.hesapla();assert.equal(a.planYillari().at(-1),2050);}finally{dom.window.close();}});
test('manual refresh downloads records and rates from one immutable revision and clears old document caches',async()=>{const {dom,w,a}=preparedApp();try{const fresh=JSON.parse(a.S.enc);fresh.parks.push({kisa:'Yeni kaynak'});const rates=JSON.parse(JSON.stringify(a.S.oran));rates.tufe.degerler={'2026':[.1]};const urls=[];w.fetch=async(u,o)=>{urls.push([u,o.cache]);return{ok:true,json:async()=>[{sha:'revision-two'}],text:async()=>JSON.stringify(u.includes('oranlar.json')?rates:fresh)};};a.S.gyp={old:true};a.S.ekB={old:true};assert.equal(await a.yenile(),true);assert.equal(a.S.veri.parks.length,2);assert.equal(a.S.dataRef,'revision-two');assert.equal(a.S.gyp,null);assert.equal(a.S.ekB,null);assert.ok(a.S.lastRefresh);assert.ok(urls.slice(1).every(([u,c])=>u.includes('ref=revision-two')&&c==='no-store'));assert.equal(a.S.tufe['2026'][0],.1);}finally{dom.window.close();}});
test('failed and offline refresh preserve current records without a success message',async()=>{const {dom,w,a}=preparedApp();try{const old=a.S.veri;w.fetch=async()=>({ok:false});assert.equal(await a.yenile(),false);assert.equal(a.S.veri,old);assert.match(w.document.querySelector('#toast').textContent,/Yeni veri alınamadı/);Object.defineProperty(w.navigator,'onLine',{value:false});w.fetch=()=>{throw Error('must not request offline');};assert.equal(await a.yenile(),false);assert.equal(a.S.veri,old);}finally{dom.window.close();}});
test('edits started during manual download prevent replacing the local draft',async()=>{const {dom,w,a}=preparedApp();try{const old=a.S.veri;w.fetch=async u=>{if(u.includes('/commits?'))return{ok:true,json:async()=>[{sha:'r2'}]};return{ok:true,text:async()=>{a.S.dirty=1;return JSON.stringify(u.includes('oranlar.json')?a.S.oran:old);}};};assert.equal(await a.yenile(),false);assert.equal(a.S.veri,old);assert.equal(a.S.dirty,1);assert.match(w.document.querySelector('#toast').textContent,/taslağınız korundu/);}finally{dom.window.close();}});
test('malformed remote records cannot replace the current application state',async()=>{const {dom,w,a}=preparedApp();try{const old=a.S.veri;w.fetch=async u=>({ok:true,json:async()=>[{sha:'bad'}],text:async()=>JSON.stringify(u.includes('oranlar.json')?a.S.oran:{parks:null})});assert.equal(await a.yenile(),false);assert.equal(a.S.veri,old);assert.equal(a.S.refreshing,false);}finally{dom.window.close();}});
test('a rate-only background revision is applied and calculations are rebuilt without changing records',async()=>{const {dom,w,a}=preparedApp();try{let opts;w.OPSync={create:o=>{opts=o;return{check:async()=>{},invalidate:()=>{}};}};a.senkronKur();const old=a.S.veri, rates=JSON.parse(JSON.stringify(a.S.oran));rates.tufe.degerler={'2026':[.22]};opts.apply({text:a.S.enc,veri:old,oran:rates,sha:'blob',ref:'rate-update'});assert.equal(a.S.veri,old);assert.equal(a.S.tufe['2026'][0],.22);assert.equal(a.S.dataRef,'rate-update');assert.match(w.document.querySelector('#toast').textContent,/Resmî oranlar güncellendi/);}finally{dom.window.close();}});

test('future year stays blank even with supplied rates until January and then recomputes from a dated annual baseline',()=>{const {dom,a}=preparedApp();try{assert.equal(a.planAl(2045).Test.kira,undefined);for(let y=2019;y<=2045;y++)a.S.oran.tufe.degerler[y]=Array(12).fill(.1);a.hesapla();assert.equal(a.planAl(2045).Test.kira,undefined);a.S.rapor='2045-01-04';a.S.pBy.Test.muh_kira=100000;a.S.pBy.Test.muh_kira_yil=2026;a.S.plan={};let cents=10000000n;for(let n=0;n<19;n++)cents=(cents*110n+50n)/100n;assert.equal(a.planAl(2045).Test.kira,Number(cents)/100);}finally{dom.window.close();}});


test('exactly seven primary modules retain active ownership for old detail routes',()=>{const {dom,w,a}=preparedApp();try{const links=[...w.document.querySelectorAll('.nav>a')];assert.deepEqual(links.map(x=>x.querySelector('span').textContent),['Genel Durum','Harita','Orman Parkları','Muhasebe','Tebliğ Ekleri','Kayıt Defteri','Tebliğ ve Hesaplar']);a.S.page='tahakkuk';a.sayfaCiz();assert.equal(w.document.querySelector('.nav a[aria-current]').dataset.p,'muhasebe');assert.match(w.document.querySelector('.module-tabs').textContent,/Alacak ve Tahsilat/);assert.equal(a.anaModul('denetim').id,'parklar');assert.equal(a.anaModul('islem').id,'defter');assert.equal(a.anaModul('hesap').id,'teblig');a.S.park='İkinci';a.sayfaCiz();assert.match(w.document.querySelector('.nav a[data-p=harita]').getAttribute('href'),/p=%C4%B0kinci/);}finally{dom.window.close();}});
