test('map picker reopens all parks after a selection, searches Turkish names and supports direct repeated selection',()=>{
 const {dom,w,a,p}=app();try{
  for(const k of ['Kurtyolu','Kayabaşı','Göktürk']){a.S.veri.parks.push({kisa:k});a.S.pBy[k]={kisa:k};a.S.gyp.parklar[k]={f:[],kaynak:[],planlar:[]};}
  w.document.querySelector('#page').innerHTML=a.SAYFA.harita();a.hParkSeciciKur();
  const input=w.document.querySelector('#hPark'),list=w.document.querySelector('#hParkL');
  input.focus();assert.equal(list.querySelectorAll('[role=option]').length,4);
  list.querySelector('[data-k="Kurtyolu"]').click();assert.equal(a.S.hP,'Kurtyolu');assert.equal(input.value,'Kurtyolu');assert.equal(list.hidden,true);
  input.click();assert.equal(list.querySelectorAll('[role=option]').length,4);
  list.querySelector('[data-k="Kayabaşı"]').click();assert.equal(a.S.hP,'Kayabaşı');assert.equal(new URLSearchParams(w.location.hash.split('?')[1]).get('p'),'Kayabaşı');
  input.click();input.value='gokturk';input.dispatchEvent(new w.Event('input'));assert.equal(list.querySelectorAll('[role=option]').length,1);input.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Enter',bubbles:true}));assert.equal(a.S.hP,'Göktürk');
  input.click();input.value='bulunmayan';input.dispatchEvent(new w.Event('input'));assert.match(list.textContent,/bulunamadı/);input.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));assert.equal(input.value,'Göktürk');assert.equal(a.S.hP,'Göktürk');
  w.document.querySelector('#hParkOpen').click();assert.equal(list.hidden,false);assert.equal(list.querySelectorAll('[role=option]').length,4);input.dispatchEvent(new w.KeyboardEvent('keydown',{key:'ArrowDown',bubbles:true}));assert.equal(input.getAttribute('aria-activedescendant'),'hParkOption0');input.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Enter',bubbles:true}));assert.equal(a.S.hP,p.kisa);
 }finally{dom.window.close();}
});
