test('live GPS watch updates point and accuracy, stops cleanly and ignores callbacks after leaving map',()=>{
 const {dom,w,a}=app();try{
  w.document.querySelector('#page').insertAdjacentHTML('afterbegin','<div id="hGps" hidden></div><div class="htools"><a data-t="kon"></a></div>');
  let success,error,cleared=[],views=[];Object.defineProperty(w.navigator,'geolocation',{value:{watchPosition:(ok,err,options)=>{success=ok;error=err;assert.equal(options.enableHighAccuracy,true);return 0;},clearWatch:id=>cleared.push(id)}});
  const layers=[];const layer=()=>{const x={addTo:()=>x,bindTooltip:()=>x,setLatLng:ll=>{x.ll=ll;return x;},setRadius:r=>{x.radius=r;return x;}};layers.push(x);return x;};w.L={circle:layer,circleMarker:layer};const map={getZoom:()=>14,setView:ll=>views.push(ll),panTo:ll=>views.push(ll),removeLayer:()=>{}};a.S._hmap=map;
  a.hKonum();assert.match(w.document.querySelector('#hGps').textContent,/bekleniyor/);success({coords:{latitude:41,longitude:28,accuracy:8},timestamp:Date.now()});assert.equal(layers.length,2);assert.match(w.document.querySelector('#hGps').textContent,/±8 m/);success({coords:{latitude:41.001,longitude:28.001,accuracy:15},timestamp:Date.now()});assert.equal(layers.length,2);assert.deepEqual(Array.from(layers[0].ll),[41.001,28.001]);assert.equal(layers[0].radius,15);
  a.S._hGpsRun.time=Date.now()-60000;a.hGpsDurum(a.S._hGpsRun);assert.match(w.document.querySelector('#hGps').textContent,/Konum eski/);
  a.hKonum();assert.deepEqual(cleared,[0]);assert.equal(a.S._hGpsRun,null);const n=views.length;success({coords:{latitude:42,longitude:29,accuracy:5},timestamp:Date.now()});assert.equal(views.length,n);
  a.hKonum();error({code:1});assert.equal(a.S._hGpsRun,null);assert.match(w.document.querySelector('#hGps').textContent,/Konum izni verilmedi/);
 }finally{dom.window.close();}
});


